fn create_row(v: &Vec<f32>, i: usize) -> Vec<f32> {
    let n = v.len();
    // For row i, place v[i] at position i, 0.0 elsewhere.
    let mut row = Vec::with_capacity(n);
    for j in 0..n {
        if j == i {
            row.push(v[i]);
        } else {
            row.push(0.0);
        }
    }
    row
}

fn diagflat(v: Vec<f32>) -> Vec<Vec<f32>> {
    let n = v.len();
    // Construct each row using create_row
    let mut matrix = Vec::with_capacity(n);
    for i in 0..n {
        matrix.push(create_row(&v, i));
    }
    matrix
}